checks.script:
python3 - <<'PY'
import math, subprocess
MASK=0xffffffff
cases={0,1,2,3,4,15,16,208,20000,MASK}
for k in (5,15,16,31,32,63,64,127,255,256,511,1023,4095,16383,32767,46340,46341,65535):
    for n in (k*k-1,k*k,k*k+1):
        if 0 <= n <= MASK: cases.add(n)
x=0x9e3779b9
for _ in range(24):
    x=(1664525*x+1013904223)&MASK
    cases.add(x)
def ref(n):
    a,b=0,1
    for _ in range(math.isqrt(n)):
        a,b=b,(a+b)&MASK
    return a
for n in sorted(cases):
    got=int(subprocess.check_output(['/app/sim',str(n)], cwd='/app', text=True).strip())
    expected=ref(n)
    if got != expected:
        raise SystemExit(f'n={n}: got {got}, expected {expected}')
print(f'{len(cases)} independent boundary/full-width cases pass')
PY

