checks.script:
set -e
cd /app
perl - <<'PL'
use strict; use warnings;
sub rc { my $x=reverse shift; $x =~ tr/ACGT/TGCA/; return $x }
sub hits { my($s,$q)=@_; my @p; while($s =~ /(?=$q)/g){push @p,$-[0]} return @p }
sub readfa { my($file)=@_; my(%x,$id); open my $f,'<',$file or die "$file: $!\n"; while(<$f>){chomp; if(/^>(\S+)\s*$/){$id=$1;$x{$id}=''} elsif(defined $id){s/\s+//g;$x{$id}.=uc $_} } return %x }
my %t=readfa('sequences.fasta'); my %p=readfa('primers.fasta');
my @parts=qw(input egfp flag snap); my %released;
for my $n (@parts) {
  my($fwd,$rev)=@p{"${n}_fwd","${n}_rev"};
  die "$n missing primer\n" unless defined $fwd && defined $rev;
  die "$n forward tail invalid\n" unless $fwd =~ /^([ACGT]{4})GGTCTC[ACGT]([ACGT]{4})([ACGT]{15,45})$/;
  my($fclamp,$foh,$fa)=($1,$2,$3);
  die "$n reverse tail invalid\n" unless $rev =~ /^([ACGT]{4})GGTCTC[ACGT]([ACGT]{4})([ACGT]{15,45})$/;
  my($rclamp,$encoded_roh,$ra)=($1,$2,$3);
  die "$n does not provide four 5-prime flanking bases for both BsaI sites\n" unless length($fclamp)==4 && length($rclamp)==4;
  my @fi=hits($t{$n},$fa); my @ri=hits($t{$n},rc($ra));
  die "$n forward annealing suffix is not uniquely on named template\n" unless @fi==1;
  die "$n reverse annealing suffix is not uniquely on named template in reverse orientation\n" unless @ri==1;
  my($a,$b)=($fi[0],$ri[0]); my $d=$b-$a; $d+=length($t{$n}) if $d<0;
  die "$n primer targets overlap\n" if $d<length($fa);
  my $middle=''; my $at=($a+length($fa))%length($t{$n});
  for(1..$d-length($fa)){$middle.=substr($t{$n},$at,1);$at=($at+1)%length($t{$n})}
  my $amp=$fwd.$middle.rc($rev);
  my @plus=hits($amp,'GGTCTC'); my @minus=hits($amp,'GAGACC');
  die "$n has unintended BsaI site(s)\n" unless @plus==1 && @minus==1 && $plus[0]==4 && $minus[0]==length($amp)-11;
  die "$n engineered sites lack amplicon flanks\n" unless substr($amp,0,4) eq $fclamp && substr($amp,-4) eq rc($rclamp);
  # BsaI's 1/5 geometry cuts the top strand 7 nt after GGTCTC and 5 nt before GAGACC.
  my $frag=substr($amp,11,length($amp)-22);
  die "$n forward sticky end disagrees with primer tail\n" unless substr($frag,0,4) eq $foh;
  die "$n reverse sticky end disagrees with reverse primer tail\n" unless substr($frag,-4) eq rc($encoded_roh);
  $released{$n}=$frag;
}
