if len(lines)!=7:
    raise SystemExit('script must have exactly seven command lines')
pat=re.compile(r'''call setreg\('([abc])', "((?:[^"\\]|\\.)*)"\)$''')
def decode(s):
    out=[]; i=0
    simple={'r':'\r','n':'\n','t':'\t','b':'\b','e':'\x1b','"':'"','\\':'\\'}
    while i<len(s):
        if s[i]!='\\': out.append(s[i]); i+=1; continue
        if i+1==len(s): raise SystemExit('dangling string escape')
        c=s[i+1]
        out.append(simple[c] if c in simple else '\\'+c)
        i+=2
    return ''.join(out)
regs={}
for line in lines[:3]:
    m=pat.fullmatch(line)
    if not m: raise SystemExit('invalid or disallowed setreg wrapper')
    name,payload=m.groups()
    if name in regs: raise SystemExit('duplicate register')
    regs[name]=decode(payload)
if set(regs)!={'a','b','c'} or any(not regs[x] for x in 'abc') or len(set(regs.values()))!=3:
    raise SystemExit('three distinct non-empty registers required')
if sum(map(len,regs.values()))>=200: raise SystemExit('macro total is not below 200')
if lines[3:]!=[':%normal! @a', ':%normal! @b', ':%normal! @c', ':wq']:
    raise SystemExit('disallowed execution or exit command')
a=regs['a']
if not (a.startswith(':s/') and a.endswith('\r') and a.count(':')==1):
    raise SystemExit('register a is not one substitution command')
if any(x in a for x in ('\n','|','!','<','>','`','\x1b')) or re.search(r'(?i)(call|function|execute|python|perl|ruby|lua|shell|source|global|normal)',a):
