        f,j=interp.parse_expr(toks,i)
        if j<=i: sys.exit('non-consuming parse: '+str(p))
        forms.append(f); i=j
    def has_read(x):
        if isinstance(x,interp.Pair):
            while isinstance(x,interp.Pair):
                if has_read(x.car): return True
                x=x.cdr
            return x is not None and has_read(x)
        return x=='read'
    if any(has_read(f) for f in forms):
        fixtures[p]=b'7\n5\n+\n'
